  1→"""MXFP4 GEMM v5: Fixed 128×128 tiling with 8-wave double-buffered LDS.
  2→
  3→Fixes from v4:
  4→1. Coverage bug: THREAD_M=8 (was 4) — now covers all 128 M rows
  5→2. Vectorized 4-byte loads from LDS
  6→3. Uses pre-quantized B_q from input (still need to re-quant for unshuffled scale)
  7→4. Properly uses at::cuda::getCurrentCUDAStream for harness compatibility
  8→
  9→Current: 13.4µs (naive 16×16) | Target: <5µs | Leader: 1.0µs
 10→"""
 11→
 12→import os
 13→
 14→os.environ["PYTORCH_ROCM_ARCH"] = "gfx950"
 15→
 16→import torch
 17→from torch.utils.cpp_extension import load_inline
 18→
 19→from aiter import dtypes
 20→from aiter.ops.triton.quant import dynamic_mxfp4_quant
 21→from task import input_t, output_t
 22→
 23→HIP_SOURCE = r"""
 24→#include <torch/extension.h>
 25→#include <hip/hip_runtime.h>
 26→#include <hip/hip_bf16.h>
 27→
 28→// ─── Tile Configuration ────────────────────────────────────────────
 29→#define BLOCK_M 128
 30→#define BLOCK_N 128
 31→#define BLOCK_K 64       // 64 FP4 elements per K tile
 32→#define BLOCK_K_BYTES 32 // 64 FP4 / 2 per byte
 33→#define THREADS 512      // 8 waves of 64
 34→
 35→// Thread mapping: 512 threads = 32 (tx) × 16 (ty)
 36→// Each thread computes THREAD_M × THREAD_N = 8 × 4 = 32 output elements
 37→// Row coverage: 16 ty × 8 = 128 = BLOCK_M ✓
 38→// Col coverage: 32 tx × 4 = 128 = BLOCK_N ✓
 39→#define THREAD_M 8
 40→#define THREAD_N 4
 41→
 42→// Scales: one E8M0 scale per 32 FP4 elements → 2 scale groups per K tile
 43→#define SCALE_GROUP_SIZE 32
 44→#define SCALES_PER_K_TILE 2
 45→
 46→// FP4 e2m1 decode LUT in constant memory (16 entries)
 47→__constant__ float FP4_LUT[16] = {
 48→    0.0f, 0.5f, 1.0f, 1.5f, 2.0f, 3.0f, 4.0f, 6.0f,
 49→    -0.0f, -0.5f, -1.0f, -1.5f, -2.0f, -3.0f, -4.0f, -6.0f
 50→};
 51→
 52→// E8M0 → float conversion
 53→__device__ __forceinline__ float e8m0_to_float(uint8_t val) {
 54→    if (val == 0 || val == 255) return 0.0f;
 55→    return exp2f((float)((int)val - 127));
 56→}
 57→
 58→// ─── Main kernel ───────────────────────────────────────────────────
 59→__global__ __launch_bounds__(THREADS, 2)
 60→void mxfp4_gemm_v5(
 61→    const uint8_t* __restrict__ A_packed,   // [M, K/2] FP4 packed
 62→    const uint8_t* __restrict__ B_packed,   // [N, K/2] FP4 packed
 63→    const uint8_t* __restrict__ A_scale,    // [M, K/32] E8M0
 64→    const uint8_t* __restrict__ B_scale,    // [N, K/32] E8M0
 65→    at::BFloat16* __restrict__ C,           // [M, N] output
 66→    int M, int N, int K
 67→) {
 68→    int bm = blockIdx.y * BLOCK_M;
 69→    int bn = blockIdx.x * BLOCK_N;
 70→    int tid = threadIdx.x;
 71→
 72→    // Thread coordinates within block
 73→    int tx = tid % 32;  // 0..31 → col dimension
 74→    int ty = tid / 32;  // 0..15 → row dimension
 75→
 76→    int K_half = K / 2;
 77→    int K_scale = K / SCALE_GROUP_SIZE;
 78→    int num_k_tiles = K / BLOCK_K;
 79→
 80→    // Double-buffered shared memory
 81→    // A tile: [BLOCK_M][BLOCK_K_BYTES] = 128 × 32 = 4KB per buffer
 82→    // B tile: [BLOCK_N][BLOCK_K_BYTES] = 128 × 32 = 4KB per buffer
 83→    // Total: 2 × (4KB + 4KB) = 16KB — well within 64KB LDS limit
 84→    __shared__ uint8_t smem_A[2][BLOCK_M * BLOCK_K_BYTES];
 85→    __shared__ uint8_t smem_B[2][BLOCK_N * BLOCK_K_BYTES];
 86→
 87→    // Register accumulators: 8 rows × 4 cols = 32 per thread
 88→    float acc[THREAD_M][THREAD_N];
 89→    #pragma unroll
 90→    for (int i = 0; i < THREAD_M; i++)
 91→        #pragma unroll
 92→        for (int j = 0; j < THREAD_N; j++)
 93→            acc[i][j] = 0.0f;
 94→
 95→    int buf = 0;
 96→
 97→    // ─── Prologue: load first K tile into buffer 0 ────────────────
 98→    {
 99→        int k_byte_off = 0;
100→        // Cooperative load: 128 × 32 = 4096 bytes / 512 threads = 8 bytes/thread
101→        for (int i = tid; i < BLOCK_M * BLOCK_K_BYTES; i += THREADS) {
102→            int row = i / BLOCK_K_BYTES;
103→            int col = i % BLOCK_K_BYTES;
104→            int gr = bm + row;
105→            smem_A[0][i] = (gr < M && (k_byte_off + col) < K_half) ?
106→                A_packed[gr * K_half + k_byte_off + col] : 0;
107→        }
108→        for (int i = tid; i < BLOCK_N * BLOCK_K_BYTES; i += THREADS) {
109→            int row = i / BLOCK_K_BYTES;
110→            int col = i % BLOCK_K_BYTES;
111→            int gr = bn + row;
112→            smem_B[0][i] = (gr < N && (k_byte_off + col) < K_half) ?
113→                B_packed[gr * K_half + k_byte_off + col] : 0;
114→        }
115→    }
116→    __syncthreads();
117→
118→    // ─── Main loop: process K tiles with double buffering ─────────
119→    for (int kt = 0; kt < num_k_tiles; kt++) {
120→        int next_kt = kt + 1;
121→        int next_buf = 1 - buf;
122→
123→        // Prefetch next K tile into alternate buffer
124→        if (next_kt < num_k_tiles) {
125→            int k_byte_off = next_kt * BLOCK_K_BYTES;
126→            for (int i = tid; i < BLOCK_M * BLOCK_K_BYTES; i += THREADS) {
127→                int row = i / BLOCK_K_BYTES;
128→                int col = i % BLOCK_K_BYTES;
129→                int gr = bm + row;
130→                smem_A[next_buf][i] = (gr < M && (k_byte_off + col) < K_half) ?
131→                    A_packed[gr * K_half + k_byte_off + col] : 0;
132→            }
133→            for (int i = tid; i < BLOCK_N * BLOCK_K_BYTES; i += THREADS) {
134→                int row = i / BLOCK_K_BYTES;
135→                int col = i % BLOCK_K_BYTES;
136→                int gr = bn + row;
137→                smem_B[next_buf][i] = (gr < N && (k_byte_off + col) < K_half) ?
138→                    B_packed[gr * K_half + k_byte_off + col] : 0;
139→            }
140→        }
141→
142→        // ─── Compute on current buffer ────────────────────────────
143→        // Each K tile = 64 FP4 elements = 2 scale groups of 32
144→        int scale_base = kt * SCALES_PER_K_TILE;
145→
146→        #pragma unroll
147→        for (int sg = 0; sg < SCALES_PER_K_TILE; sg++) {
148→            int scale_idx = scale_base + sg;
149→            int byte_off = sg * 16;  // 16 bytes = 32 FP4 elements per scale group
150→
151→            // Each thread processes its 8×4 sub-tile
152→            #pragma unroll
153→            for (int mi = 0; mi < THREAD_M; mi++) {
154→                int row_local = ty * THREAD_M + mi;
155→                int row_global = bm + row_local;
156→                if (row_global >= M) continue;
157→
158→                // Load A scale once per row per scale group
159→                float sa = e8m0_to_float(A_scale[row_global * K_scale + scale_idx]);
160→
161→                #pragma unroll
162→                for (int ni = 0; ni < THREAD_N; ni++) {
163→                    int col_local = tx * THREAD_N + ni;
164→                    int col_global = bn + col_local;
165→                    if (col_global >= N) continue;
166→
167→                    // Load B scale once per col per scale group
168→                    float sb = e8m0_to_float(B_scale[col_global * K_scale + scale_idx]);
169→
170→                    // Inner product over 32 FP4 elements (16 packed bytes)
171→                    float dot = 0.0f;
172→
173→                    // Vectorized: load 4 bytes at a time (8 FP4 values)
174→                    #pragma unroll
175→                    for (int kb4 = 0; kb4 < 4; kb4++) {
176→                        int base_a = row_local * BLOCK_K_BYTES + byte_off + kb4 * 4;
177→                        int base_b = col_local * BLOCK_K_BYTES + byte_off + kb4 * 4;
178→
179→                        // 4-byte vectorized load from LDS
180→                        uint32_t a4 = *reinterpret_cast<const uint32_t*>(&smem_A[buf][base_a]);
181→                        uint32_t b4 = *reinterpret_cast<const uint32_t*>(&smem_B[buf][base_b]);
182→
183→                        // Unpack and accumulate 8 FP4 pairs from 4 bytes
184→                        #pragma unroll
185→                        for (int i = 0; i < 4; i++) {
186→                            uint8_t ab = (a4 >> (i * 8)) & 0xFF;
187→                            uint8_t bb = (b4 >> (i * 8)) & 0xFF;
188→                            dot += FP4_LUT[ab & 0xF] * FP4_LUT[bb & 0xF];
189→                            dot += FP4_LUT[(ab >> 4) & 0xF] * FP4_LUT[(bb >> 4) & 0xF];
190→                        }
