HIP_SOURCE = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>

// ─── Tile Configuration ────────────────────────────────────────────
#define BLOCK_M 128
#define BLOCK_N 128
#define BLOCK_K 64       // 64 FP4 elements per K tile
#define BLOCK_K_BYTES 32 // 64 FP4 / 2 per byte
#define THREADS 512      // 8 waves of 64

// Thread mapping: 512 threads = 32 (tx) × 16 (ty)
// Each thread computes THREAD_M × THREAD_N = 8 × 4 = 32 output elements
// Row coverage: 16 ty × 8 = 128 = BLOCK_M ✓
// Col coverage: 32 tx × 4 = 128 = BLOCK_N ✓
#define THREAD_M 8
#define THREAD_N 4

// Scales: one E8M0 scale per 32 FP4 elements → 2 scale groups per K tile
#define SCALE_GROUP_SIZE 32
#define SCALES_PER_K_TILE 2

// FP4 e2m1 decode LUT in constant memory (16 entries)
__constant__ float FP4_LUT[16] = {
    0.0f, 0.5f, 1.0f, 1.5f, 2.0f, 3.0f, 4.0f, 6.0f,
    -0.0f, -0.5f, -1.0f, -1.5f, -2.0f, -3.0f, -4.0f, -6.0f
};

// E8M0 → float conversion
__device__ __forceinline__ float e8m0_to_float(uint8_t val) {
    if (val == 0 || val == 255) return 0.0f;
    return exp2f((float)((int)val - 127));
}

// ─── Main kernel ───────────────────────────────────────────────────
__global__ __launch_bounds__(THREADS, 2)
void mxfp4_gemm_v5(
    const uint8_t* __restrict__ A_packed,   // [M, K/2] FP4 packed
    const uint8_t* __restrict__ B_packed,   // [N, K/2] FP4 packed
    const uint8_t* __restrict__ A_scale,    // [M, K/32] E8M0
    const uint8_t* __restrict__ B_scale,    // [N, K/32] E8M0
    at::BFloat16* __restrict__ C,           // [M, N] output
    int M, int N, int K
) {
    int bm = blockIdx.y * BLOCK_M;
    int bn = blockIdx.x * BLOCK_N;
    int tid = threadIdx.x;

    // Thread coordinates within block
    int tx = tid % 32;  // 0..31 → col dimension
    int ty = tid / 32;  // 0..15 → row dimension

    int K_half = K / 2;
    int K_scale = K / SCALE_GROUP_SIZE;
    int num_k_tiles = K / BLOCK_K;

    // Double-buffered shared memory
    // A tile: [BLOCK_M][BLOCK_K_BYTES] = 128 × 32 = 4KB per buffer
    // B tile: [BLOCK_N][BLOCK_K_BYTES] = 128 × 32 = 4KB per buffer
    // Total: 2 × (4KB + 4KB) = 16KB — well within 64KB LDS limit
    __shared__ uint8_t smem_A[2][BLOCK_M * BLOCK_K_BYTES];
    __shared__ uint8_t smem_B[2][BLOCK_N * BLOCK_K_BYTES];

    // Register accumulators: 8 rows × 4 cols = 32 per thread
    float acc[THREAD_M][THREAD_N];
    #pragma unroll
    for (int i = 0; i < THREAD_M; i++)
        #pragma unroll
        for (int j = 0; j < THREAD_N; j++)
            acc[i][j] = 0.0f;

    int buf = 0;

    // ─── Prologue: load first K tile into buffer 0 ────────────────
    {
        int k_byte_off = 0;
        // Cooperative load: 128 × 32 = 4096 bytes / 512 threads = 8 bytes/thread
        for (int i = tid; i < BLOCK_M * BLOCK_K_BYTES; i += THREADS) {
            int row = i / BLOCK_K_BYTES;
            int col = i % BLOCK_K_BYTES;
            int gr = bm + row;
            smem_A[0][i] = (gr < M && (k_byte_off + col) < K_half) ?
                A_packed[gr * K_half + k_byte_off + col] : 0;
        }
        for (int i = tid; i < BLOCK_N * BLOCK_K_BYTES; i += THREADS) {
            int row = i / BLOCK_K_BYTES;
            int col = i % BLOCK_K_BYTES;
            int gr = bn + row;
            smem_B[0][i] = (gr < N && (k_byte_off + col) < K_half) ?
                B_packed[gr * K_half + k_byte_off + col] : 0;
        }
    }
    __syncthreads();

    // ─── Main loop: process K tiles with double buffering ─────────
    for (int kt = 0; kt < num_k_tiles; kt++) {
        int next_kt = kt + 1;
        int next_buf = 1 - buf;

        // Prefetch next K tile into alternate buffer
        if (next_kt < num_k_tiles) {
            int k_byte_off = next_kt * BLOCK_K_BYTES;
            for (int i = tid; i < BLOCK_M * BLOCK_K_BYTES; i += THREADS) {
                int row = i / BLOCK_K_BYTES;
                int col = i % BLOCK_K_BYTES;
                int gr = bm + row;
                smem_A[next_buf][i] = (gr < M && (k_byte_off + col) < K_half) ?
                    A_packed[gr * K_half + k_byte_off + col] : 0;
            }
            for (int i = tid; i < BLOCK_N * BLOCK_K_BYTES; i += THREADS) {
                int row = i / BLOCK_K_BYTES;
                int col = i % BLOCK_K_BYTES;
                int gr = bn + row;
                smem_B[next_buf][i] = (gr < N && (k_byte_off + col) < K_half) ?
                    B_packed[gr * K_half + k_byte_off + col] : 0;
            }
        }

        // ─── Compute on current buffer ────────────────────────────
        // Each K tile = 64 FP4 elements = 2 scale groups of 32
        int scale_base = kt * SCALES_PER_K_TILE;

        #pragma unroll
        for (int sg = 0; sg < SCALES_PER_K_TILE; sg++) {
            int scale_idx = scale_base + sg;
            int byte_off = sg * 16;  // 16 bytes = 32 FP4 elements per scale group

            // Each thread processes its 8×4 sub-tile
            #pragma unroll
            for (int mi = 0; mi < THREAD_M; mi++) {
                int row_local = ty * THREAD_M + mi;
                int row_global = bm + row_local;
                if (row_global >= M) continue;

                // Load A scale once per row per scale group
                float sa = e8m0_to_float(A_scale[row_global * K_scale + scale_idx]);

                #pragma unroll
                for (int ni = 0; ni < THREAD_N; ni++) {
                    int col_local = tx * THREAD_N + ni;
                    int col_global = bn + col_local;
                    if (col_global >= N) continue;

                    // Load B scale once per col per scale group
                    float sb = e8m0_to_float(B_scale[col_global * K_scale + scale_idx]);

                    // Inner product over 32 FP4 elements (16 packed bytes)
                    float dot = 0.0f;

                    // Vectorized: load 4 bytes at a time (8 FP4 values)
                    #pragma unroll
                    for (int kb4 = 0; kb4 < 4; kb4++) {
                        int base_a = row_local * BLOCK_K_BYTES + byte_off + kb4 * 4;
                        int base_b = col_local * BLOCK_K_BYTES + byte_off + kb4 * 4;

                        // 4-byte vectorized load from LDS
                        uint32_t a4 = *reinterpret_cast<const uint32_t*>(&smem_A[buf][base_a]);
                        uint32_t b4 = *reinterpret_cast<const uint32_t*>(&smem_B[buf][base_b]);

                        // Unpack and accumulate 8 FP4 pairs from 4 bytes
                        #pragma unroll
                        for (int i = 0; i < 4; i++) {
                            uint8_t ab = (a4 >> (i * 8)) & 0xFF;
                            uint8_t bb = (b4 >> (i * 8)) & 0xFF;
                            dot += FP4_LUT[ab & 0xF] * FP4_LUT[bb & 0xF];
                            dot += FP4_LUT[(ab >> 4) & 0xF] * FP4_LUT[(bb >> 4) & 0xF];
                        }
                    }

                    acc[mi][ni] += dot * sa * sb;
                }
            }
        }

        __syncthreads();
        buf = next_buf;
    }

    // ─── Epilogue: write results ──────────────────────────────────
    #pragma unroll
    for (int mi = 0; mi < THREAD_M; mi++) {
        int row = bm + ty * THREAD_M + mi;
        if (row >= M) continue;

        #pragma unroll
        for (int ni = 0; ni < THREAD_N; ni++) {
            int col = bn + tx * THREAD_N + ni;
            if (col >= N) continue;
            C[row * N + col] = __float2bfloat16(acc[mi][ni]);
        }
    }
}

// ─── Python binding ───────────────────────────────────────────────
torch::Tensor mxfp4_gemm_v5_launch(
    torch::Tensor A_packed,
    torch::Tensor B_packed,
    torch::Tensor A_scale,
    torch::Tensor B_scale,
    int M, int N, int K
) {
    auto C = torch::empty({M, N}, torch::TensorOptions()
        .dtype(torch::kBFloat16)
        .device(A_packed.device()));

    dim3 block(THREADS);
    dim3 grid((N + BLOCK_N - 1) / BLOCK_N, (M + BLOCK_M - 1) / BLOCK_M);

    mxfp4_gemm_v5<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
        A_packed.data_ptr<uint8_t>(),
        B_packed.data_ptr<uint8_t>(),
        A_scale.data_ptr<uint8_t>(),
        B_scale.data_ptr<uint8_t>(),
        reinterpret_cast<at::BFloat16*>(C.data_ptr()),
        M, N, K
    );
    return C;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("mxfp4_gemm_v5_launch", &mxfp4_gemm_v5_launch, "MXFP4 GEMM v5");
}
