int launch_mla_stage1(
    torch::Tensor logits,       // [splits, total_q, heads, v_dim] f32
    torch::Tensor attn_lse,     // [splits, total_q, heads] f32
    torch::Tensor q_fp8,        // [total_q, heads, qk_head_dim] fp8
    torch::Tensor kv_4d,        // [pages, page_size, kv_heads, qk_head_dim] fp8
    torch::Tensor kv_indptr,    // [batch+1] int32
    torch::Tensor kv_indices,   // [total_kv_pages] int32
    torch::Tensor kv_last_len,  // [batch] int32
    torch::Tensor qo_indptr,    // [batch+1] int32
    torch::Tensor work_meta,    // work_meta_data buffer
    torch::Tensor work_indptr,  // work_indptr buffer
    torch::Tensor output,       // [total_q, heads, v_dim] bf16
    torch::Tensor q_scale,      // [1] f32
    torch::Tensor kv_scale,     // [1] f32
    float sm_scale,
    int qseqlen,
    int num_kv_splits,
    int gqa_ratio
) {
    if (!ensure_loaded()) return -1;

    // Build the packed args struct
    MlaKernelArgs args;
    memset(&args, 0, sizeof(args));

    args.ptr_R       = logits.data_ptr();
    args.ptr_LSE     = attn_lse.data_ptr();
    args.ptr_Q       = q_fp8.data_ptr();
    args.ptr_KV      = kv_4d.data_ptr();
    args.ptr_LTP     = kv_indptr.data_ptr();
    args.ptr_LTD     = kv_indices.data_ptr();
    args.ptr_LTL     = kv_last_len.data_ptr();
    args.scalar      = sm_scale;
    args.s_MQA       = (uint32_t)(gqa_ratio * qseqlen);
    args.s_kv_split  = (uint32_t)num_kv_splits;

    // Q stride in bytes: q_fp8.stride(0) * element_size * qseqlen
    int64_t q_stride_bytes = q_fp8.stride(0) * q_fp8.element_size();
    args.s_Q_Bs      = (uint32_t)(q_stride_bytes * qseqlen);

    // KV page stride in bytes: kv_4d.stride(0) * element_size
    args.s_Bs        = (uint32_t)(kv_4d.stride(0) * kv_4d.element_size());
    args.s_log2_plen = 0;  // log2(PAGE_SIZE=1) = 0

    args.ptr_QTP        = qo_indptr.data_ptr();
    args.ptr_STP        = work_meta.data_ptr();
    args.ptr_RP         = output.data_ptr();
    args.ptr_QSCALE     = q_scale.data_ptr();
    args.ptr_KVSCALE    = kv_scale.data_ptr();
    args.out_16_nosplit = (uint32_t)num_kv_splits;
    args.ptr_LSEP       = nullptr;

    // Build HIP launch config for BUFFER_POINTER style
    size_t arg_size = sizeof(args);
    void* config[] = {
        (void*)0x01,  // HIP_LAUNCH_PARAM_BUFFER_POINTER
        (void*)&args,
        (void*)0x02,  // HIP_LAUNCH_PARAM_BUFFER_SIZE
        (void*)&arg_size,
        (void*)0x03   // HIP_LAUNCH_PARAM_END
    };

    // Grid: persistent mode, one block per work unit
    unsigned int gdx = (unsigned int)(work_indptr.size(0) - 1);

    // KEY: at::cuda::getCurrentCUDAStream() returns the HARNESS stream
    // This is why load_inline works where ctypes failed!
    hipStream_t stream = at::cuda::getCurrentCUDAStream();

    hipError_t err = hipModuleLaunchKernel(
        s_mla_func,
        gdx, 1, 1,     // grid
        256, 1, 1,      // block (4 wavefronts of 64)
        0,              // shared memory
        stream,         // CORRECT stream from harness
        nullptr,        // kernelParams (nullptr for BUFFER_POINTER)
        config          // extra config with packed args
    );

    return (err == hipSuccess) ? 0 : (int)err;
}

