__global__ void mxfp4_gemm_mfma(
    const uint8_t* __restrict__ A,   // [M, K/2]
    const uint8_t* __restrict__ B,   // [N, K/2]
    const uint8_t* __restrict__ As,  // [M, K/32]
    const uint8_t* __restrict__ Bs,  // [N, K/32]
    __hip_bfloat16* __restrict__ C,
    int M, int N, int K
) {
    int bm = blockIdx.y * TILE_M;
    int bn = blockIdx.x * TILE_N;
    int tid = threadIdx.x;

    int K_half = K / 2;
    int K_scale = K / 32;
    int num_k_tiles = K / TILE_K;

    // LDS: contiguous 32x32 byte blocks for A and B tiles
    // This matches the blog's flat array layout exactly
    __shared__ uint8_t lds_a[32 * 32];  // [32 rows][32 bytes] = 1024 bytes
    __shared__ uint8_t lds_b[32 * 32];  // [32 rows][32 bytes] = 1024 bytes

    fp32x16_t c_reg = {};
    for (int i = 0; i < 16; i++) c_reg[i] = 0.0f;

