        // B: blog pattern — ldg_b = B + (t%32)/2 + 16*32*(t/32)
        const uint8_t* ldg_b = lds_b + (tid % 32) / 2 + 16 * 32 * (tid / 32);
        int b_extract_idx = tid % 2;
