            mla_reduce_v1(m["logits"], m["lse"], m["ri"], m["rfm"], m["rpm"], qsl, m["out"])
            return m["out"]

    # Fallback: standard aiter
    from aiter.mla import mla_decode_stage1_asm_fwd
    mla_decode_stage1_asm_fwd(
        q_fp8.view(-1, NUM_HEADS, QK_HEAD_DIM), kv_4d, qo_indptr, kv_indptr,
        m["kvi"], m["kvl"], None, m["wm"], m["wi"], m["wis"],
        qsl, PAGE_SIZE, NUM_KV_HEADS, SM_SCALE, m["logits"], m["lse"], m["out"],
        q_scale=q_scale, kv_scale=kv_scale)
    mla_reduce_v1(m["logits"], m["lse"], m["ri"], m["rfm"], m["rpm"], qsl, m["out"])
    return m["out"]

